      ALIAS_CONTRACTS = {
        ChatProvider: [ "Marks a class as a chat provider a plugin supplies for the chat agent loop; turn orchestration, queueing and session persistence are not promised.", %w[] ],
        CableChannel: [ "Bases plugin-owned Action Cable channels; connection authentication and stream naming of core channels are not promised.", %w[] ],
        PlatformPollingJob: [ "Bases a platform-delivery polling job (at most one live instance per key); scheduling and deduplication internals are not promised.", %w[] ],
        InboundMessageRouter: [ "Routes an inbound platform message to the chat or job it belongs to; routing rules and the returned result members are not promised beyond new.", %w[new] ],
        BugReportRouter: [ "Resolves the repository a bug report about Syrus itself should be filed against for a user; routing rules are not promised.", %w[new target_repository] ],
        TypedArtifactRenderer: [ "Enriches a workflow's typed artifacts with their rendered presentation; the renderers themselves are not promised.", %w[enrich] ],
        ColorPalette: [ "Reads the agent accent-color palette: HEX_PATTERN validates a color, default_agent_order lists the defaults and next_default_color picks one not yet used; the colors themselves may change between releases.", %w[HEX_PATTERN default_agent_order next_default_color] ],
        ThemeRecord: [ "Reads and writes user-owned themes (find_by, where, exists?, new, find_or_initialize_by, selectable_by, terracotta) and exposes the TOKEN_KEYS and EXTENDED_TOKEN_GROUPS vocabularies themes validate against; the stored columns and built-in themes are not promised.", %w[find_by where exists? new find_or_initialize_by selectable_by terracotta TOKEN_KEYS EXTENDED_TOKEN_GROUPS] ],
        UiEngagementSampleRecord: [ "Queries recorded UI engagement samples by user and time; columns beyond those filters are not promised.", %w[where] ],
        ChatProposalRecord: [ "Queries chat proposals joined to their chat session; columns beyond the join and filters are not promised. Chat is planned to become a plugin, so this contract may move with it.", %w[joins where] ],
        ChatSpendEntryRecord: [ "Queries per-chat spend entries (all, where, joins); columns beyond the filters are not promised. Chat is planned to become a plugin, so this contract may move with it.", %w[all where joins] ],
        ChatWakeupRecord: [ "Queries scheduled chat wakeups (pending, where); columns beyond the filters are not promised. Chat is planned to become a plugin, so this contract may move with it.", %w[pending where] ],
        ChatAttachmentRecord: [ "Queries what a chat session has attached to a record (where); columns beyond the attachable filters are not promised. Chat is planned to become a plugin, so this contract may move with it.", %w[where] ],
        ChatAssociatedJobs: [ "Scopes jobs associated with the given chat sessions (scope_for); association rules are not promised.", %w[scope_for] ],
        ChatLockErrors: [ "Controller concern that renders a temporary chat-lock error response and detects transient lock errors; only those helpers are promised.", %w[render_temporary_chat_lock_error transient_chat_lock_error?] ],
        ChatWorkEvents: [ "Publishes a work event into a chat (publish!); severity vocabulary and event storage are not promised.", %w[publish!] ],
        ChatResultBadges: [ "Builds result badges for a set of chat sessions (for); badge kinds are not promised.", %w[for] ],
        ChatMediaLibrary: [ "Materializes a captured image into a chat session's media library (materialize_captured_image!); media storage is not promised.", %w[materialize_captured_image!] ],
        ChatHistoryTranscriptRenderer: [ "Renders a chat's history as recovery context for a resumed agent session (resume_recovery); the transcript format is not promised.", %w[resume_recovery] ],
        ChatContextCompactor: [ "Answers whether context compaction is enabled for a chat and supplies its compacted context messages; compaction itself is not promised.", %w[enabled_for? context_messages_for] ],
        ChatSessionRehydrator: [ "Registers a per-provider rehydrator that rebuilds an agent session from chat history (register); provider plugins define their rehydrators under this namespace.", %w[register] ],
        ChatSessionRecord: [ "Chat-session persistence used by chat-surface plugins; only the listed queries, scopes, construction hooks, extension hooks and vocabularies are public.", %w[find find_by find_by! where none active create! fallback_title_for reflect_on_association has_one prepend define_method remove_method instance_methods EFFORT_LEVELS CrossChatMessage] ],
        ChatMessageRecord: [ "Chat-message persistence used by chat-surface plugins; only the listed queries, scopes and extension hooks are public.", %w[find find_by where none active include set_callback skip_callback] ],
        ChatPendingActionRecord: [ "Pending chat-action persistence used by permission and coworker plugins; only the listed queries, scopes and checkpoint vocabulary are public.", %w[where none pending NONTERMINAL_CHECKPOINT_STATES] ],
        ChatBridgeThreadRecord: [ "Persists a bridge between chat threads; only basic lookup and creation are public.", %w[find_by create!] ],
        ChatQueuedMessageRecord: [ "Exposes the internal-role metadata key used when a plugin queues a host-delivered chat message.", %w[INTERNAL_ROLE_KEY] ],
        ChatQueuedMessagePromoter: [ "Promotes one queued chat message when its target chat is idle.", %w[deliver_one_if_idle!] ],
        ChatSessionLifecycle: [ "Controller concern for the host chat-session lifecycle; only inclusion in app controllers is public.", %w[] ],
        ChatSessionCreator: [ "Creates chat sessions through the host lifecycle and safely enqueues their first turn.", %w[new enqueue_turn] ],
        ChatTurnJob: [ "Enqueues a host-managed chat turn.", %w[perform_later] ],
        Mentionable: [ "Mixin for records that participate in chat mentions; implementing classes provide the mention identity and addressability methods.", %w[KINDS] ],
        MentionableResolver: [ "Resolves mention syntax and mention identities through host and plugin providers.", %w[resolve find] ],
        ChatWorkspace: [ "Resolves a chat's on-disk workspace paths (path_for, repo_path_for, agent_home_for), creates its root (ensure_root!) and reads checkout state (uncommitted_changes?, rebase_in_progress?); workspace layout beyond these is not promised.", %w[path_for repo_path_for agent_home_for ensure_root! uncommitted_changes? rebase_in_progress?] ],
        PreviewPanelRecord: [ "Reads preview panels visible to a user (accessible_to), opens and updates them through Service, serializes them through Payload and exposes DEFAULT_ENTRY_FILENAME; storage and versioning are not promised.", %w[accessible_to Service Payload DEFAULT_ENTRY_FILENAME] ],
        PreviewPanelVersionRecord: [ "Queries the built versions of preview panels (where); columns beyond the filters are not promised.", %w[where] ],
        PreviewCommandSource: [ "Resolves the command that starts a workspace's preview from its configuration; resolution rules are not promised.", %w[new resolve] ],
        PreviewProcessLauncher: [ "Launches a workspace's preview process on a port (launch!); process supervision is not promised.", %w[new launch!] ],
        RuntimeSessionRecord: [ "Finds a runtime session by id; state transitions, persistence and other associations are not promised. Runtime-session plugins implement Syrus::Host::RuntimeSessionProvider.", %w[find] ],
        RuntimeControlLease: [ "Audits rejected agent input against a runtime session (audit_input_rejected!) and runs a block under agent input control (with_agent_input_control); lease acquisition and expiry are not promised.", %w[audit_input_rejected! with_agent_input_control] ],
